/** Real Paper commands, native clients and inventory handlers; no mock storage or integration stubs. */
final class AdministrationRuntimeProbe {
    final JavaPlugin plugin;final InvestigationApplication admin;final ReputationApplication profiles;final VotingService voting;final ReputationPolicyService policies;
    Player operator,voter,target;UUID first,pending;final List<InvestigationApplication.Committed> events=new CopyOnWriteArrayList<>();
    final NamespacedKey own=new NamespacedKey("dexturreputation","reputation-health"),foreign=new NamespacedKey("phase7qa","foreign-health");
    AdministrationRuntimeProbe(JavaPlugin plugin)throws Exception{this.plugin=plugin;profiles=(ReputationApplication)plugin.getServer().getServicesManager().load(ReputationService.class);voting=plugin.getServer().getServicesManager().load(VotingService.class);policies=plugin.getServer().getServicesManager().load(ReputationPolicyService.class);var owner=plugin.getServer().getPluginManager().getPlugin("DexturReputation");var method=owner.getClass().getDeclaredMethod("investigationAdministration");method.setAccessible(true);admin=(InvestigationApplication)method.invoke(owner);}
    void start(Runnable success,Consumer<Throwable> failure){Path marker=plugin.getDataFolder().toPath().resolve("administration-restart.txt");boolean restart=Files.exists(marker);AutoCloseable subscription=admin.onCommitted(events::add);
        poll(()->main(()->{operator=plugin.getServer().getPlayerExact("Phase7Admin");voter=plugin.getServer().getPlayerExact("Phase7Voter");target=plugin.getServer().getPlayerExact("Phase7Target");return operator!=null&&voter!=null&&target!=null;}),Boolean::booleanValue,0)
        .thenCompose(v->voting.view(target.getUniqueId())).thenCompose(v->main(()->{operator.performCommand("repadmin inspect Phase7Target");operator.performCommand("repadmin invalidate 00000000-0000-0000-0000-000000000001 denied");var attachment=operator.addAttachment(plugin);for(String permission:List.of("inspect","history","vote.inspect","vote.invalidate","vote.restore","pending.view","pending.approve","pending.reject","trust.inspect","flags.inspect","flags.resolve","relations.inspect","recalculate.reputation","recalculate.trust","recalculate.tier","recalculate.all","audit","gui","bulk"))attachment.setPermission("dexturreputation.admin."+permission,true);operator.performCommand("rep language en_US");var health=target.getAttribute(Attribute.MAX_HEALTH);if(health.getModifier(foreign)==null)health.addTransientModifier(new AttributeModifier(foreign,4,AttributeModifier.Operation.ADD_NUMBER));return true;}))
        .thenCompose(v->poll(()->main(()->profiles.cachedLanguage(operator.getUniqueId())==org.dextur.reputation.domain.PlayerLanguage.en_US),Boolean::booleanValue,0))
        .thenCompose(v->{if(!restart)return firstRun();return auditIds().thenCompose(ids->{try{check(Files.readString(marker).equals(ids),"Restart duplicated or lost moderation audit");check(events.isEmpty(),"Restart replayed moderation events");return voting.view(target.getUniqueId());}catch(Exception e){return CompletableFuture.failedFuture(e);}}).thenApply(view->{check(view.profile().visibleScore()==100,"Restart reputation/admin projection lost");return true;});})
        .thenCompose(v->stagedOperation(restart)).thenCompose(v->localesAndReadCommands()).thenCompose(v->guiOverview()).thenCompose(v->guiLocales())
        .thenCompose(v->policies.evaluate(target.getUniqueId(),"health.maximum"))
        .thenCompose(v->poll(()->main(()->{var a=target.getAttribute(Attribute.MAX_HEALTH);return a.getValue()==25&&a.getModifier(foreign)!=null&&a.getModifiers().stream().filter(m->m.getKey().equals(own)).count()==1;}),Boolean::booleanValue,0))
        .thenCompose(v->plugin.getServer().getPluginManager().isPluginEnabled("LuckPerms")?new LuckPermsRuntimeProbe(plugin).verifyOnline(target.getUniqueId()).thenApply(x->true):CompletableFuture.completedFuture(true))
        .thenCompose(v->poll(()->main(this::papi),Boolean::booleanValue,0)).thenCompose(v->auditIds())
        .thenCompose(ids->main(()->{Files.createDirectories(marker.getParent());Files.writeString(marker,ids);operator.performCommand("repadmin gui Phase7Target");plugin.getLogger().info("PROBE_ADMINISTRATION_PASS: native inspect/vote/moderation/pending/Trust/flags/relations/recalculation/audit, dry-run/actor-bound confirmation/batches, GUI/locales, exact weights and restart");return true;}))
        .whenComplete((v,error)->main(()->{try{subscription.close();if(error!=null)failure.accept(error);else success.run();}catch(Throwable failed){failure.accept(failed);}return null;}));
    }
    private CompletionStage<Boolean> firstRun(){return main(()->{voter.performCommand("like Phase7Target helpful Phase 7 native");return true;})
        .thenCompose(v->poll(()->voting.history(target.getUniqueId(),VotePage.Direction.RECEIVED,1),page->page.totalEntries()==1,0)).thenApply(page->{first=page.entries().getFirst().entry().operationId();return true;})
        .thenCompose(v->main(()->{operator.performCommand("repadmin invalidate "+first+" Player UUID audit");return true;})).thenCompose(v->outcome(first,VoteProcessingOutcome.Status.INVALIDATED))
        .thenCompose(v->console("repadmin restore "+first+" Correct moderation mistake")).thenCompose(v->outcome(first,VoteProcessingOutcome.Status.ACCEPTED))
        .thenCompose(v->main(()->{operator.performCommand("dislike Phase7Target rude first negative");return true;}))
        .thenCompose(v->poll(()->voting.history(target.getUniqueId(),VotePage.Direction.RECEIVED,1),page->page.totalEntries()==2,0))
        .thenCompose(v->main(()->{voter.performCommand("dislike Phase7Target rude pending replacement");return true;}))
        .thenCompose(v->poll(()->voting.history(target.getUniqueId(),VotePage.Direction.RECEIVED,1),page->page.totalEntries()==3,0)).thenApply(page->{pending=page.entries().getFirst().entry().operationId();return true;})
        .thenCompose(v->outcome(pending,VoteProcessingOutcome.Status.PENDING))
        .thenCompose(v->console("repadmin pending reject "+pending+" Review rejection")).thenCompose(v->outcome(pending,VoteProcessingOutcome.Status.INVALIDATED))
        .thenCompose(v->console("repadmin restore "+pending+" Restore pending state")).thenCompose(v->outcome(pending,VoteProcessingOutcome.Status.PENDING))
        .thenCompose(v->console("repadmin pending approve "+pending+" Reviewed exact weight")).thenCompose(v->outcome(pending,VoteProcessingOutcome.Status.ACCEPTED))
        .thenCompose(v->voting.view(target.getUniqueId())).thenApply(view->{check(view.profile().communityScore()==-1,"Exact -0.70 contribution was not projected");check(view.statistics().historyEntries()==3,"Moderation manufactured votes");return true;})
        .thenCompose(v->read(Section.FLAGS,target.getUniqueId(),null)).thenCompose(report->{check(!report.rows().isEmpty(),"Detector flags missing");UUID flag=report.rows().getFirst().id();return console("repadmin flag "+flag+" FALSE_POSITIVE resolved after review").thenCompose(x->poll(()->read(Section.FLAGS,target.getUniqueId(),null),r->r.rows().stream().anyMatch(row->row.id().equals(flag)&&row.values().get("status").equals("FALSE_POSITIVE")),0)).thenApply(x->true);})
        .thenCompose(v->dryRunAndBulk())
        .thenCompose(v->console("repadmin set Phase7Target 100 Phase 6 command preserved")).thenCompose(v->poll(()->voting.view(target.getUniqueId()),view->view.profile().visibleScore()==100,0))
        .thenCompose(v->recalculations())
        .thenCompose(v->guiModeration()).thenCompose(v->offlineInspection())
        .thenCompose(v->read(Section.AUDIT,target.getUniqueId(),null)).thenApply(report->{check(report.rows().stream().anyMatch(row->row.values().get("actor").equals(operator.getUniqueId().toString())),"Native administrator UUID missing in audit");check(events.stream().anyMatch(e->e.kind().equals("VoteInvalidated"))&&events.stream().anyMatch(e->e.kind().equals("PendingVoteReviewed"))&&events.stream().anyMatch(e->e.kind().equals("AdministrationBulkOperationCompleted")),"Committed events missing");return true;});
    }
    private CompletionStage<Boolean> stagedOperation(boolean restart){Path file=plugin.getDataFolder().toPath().resolve("staged-operation.txt");if(restart){try{return read(Section.OPERATION,null,UUID.fromString(Files.readString(file))).thenApply(report->{check(report.rows().stream().anyMatch(row->row.values().get("status").equals("RUNNING")&&row.values().get("cursor").equals("0")),"Restart resumed/lost staged operation");return true;});}catch(Exception e){return CompletableFuture.failedFuture(e);}}UUID operation=UUID.randomUUID();return admin.plan(Action.INVALIDATE,new Filter(null,target.getUniqueId(),null,"",null,null,"","",null),"CONSOLE","QA staged resumable migration").thenCompose(plan->admin.stage(operation,plan)).thenCompose(record->main(()->{Files.writeString(file,operation.toString());check(record.status().equals("RUNNING")&&record.values().get("cursor").equals("0"),"Staged operation executed automatically");return true;}));}
    private CompletionStage<Boolean> recalculations(){CompletionStage<Boolean> chain=CompletableFuture.completedFuture(true);for(String kind:List.of("reputation","trust","tier","all"))chain=chain.thenCompose(v->auditIds()).thenCompose(before->console("repadmin recalculate "+kind+" Phase7Target Explicit runtime reconciliation").thenCompose(x->poll(this::auditIds,after->!after.equals(before),0)).thenApply(x->true));return chain;}
    private CompletionStage<Boolean> dryRunAndBulk(){return auditIds().thenCompose(before->capture(false,"bulk","invalidate","target","Phase7Target","dry-run reason","--type=DISLIKE","--dry-run").thenCompose(replies->poll(()->main(()->replies.stream().anyMatch(text->text.contains("данные не изменены"))),Boolean::booleanValue,0)).thenCompose(v->auditIds()).thenApply(after->{check(before.equals(after),"Dry run wrote audit/state");return true;}))
        .thenCompose(v->bulk("invalidate")).thenCompose(v->outcome(pending,VoteProcessingOutcome.Status.INVALIDATED)).thenCompose(v->bulk("restore")).thenCompose(v->outcome(pending,VoteProcessingOutcome.Status.ACCEPTED));}
    private CompletionStage<Boolean> bulk(String action){return capture(false,"bulk",action,"target","Phase7Target","Explicit bulk runtime reason","--type=DISLIKE").thenCompose(replies->poll(()->main(()->token(replies)),Objects::nonNull,0)).thenCompose(token->capture(false,"confirm",token).thenCompose(replies->poll(()->main(()->replies.stream().anyMatch(t->t.contains("обработано 2/2"))),Boolean::booleanValue,0))).thenApply(v->true);}
    private static String token(List<String> replies){var pattern=java.util.regex.Pattern.compile("/repadmin confirm ([A-F0-9]{16})");for(var reply:replies){var m=pattern.matcher(reply);if(m.find())return m.group(1);}return null;}
    private CompletionStage<Boolean> guiOverview(){return main(()->{operator.performCommand("repadmin gui Phase7Target");return true;}).thenCompose(v->guiReady("INSPECT")).thenCompose(v->{CompletionStage<Boolean> chain=CompletableFuture.completedFuture(true);var names=List.of("INSPECT","VOTES","PENDING","TRUST","FLAGS","RELATIONS","RECOVERY","ADMIN","AUDIT","RECALCULATE");for(int i=0;i<names.size();i++){int slot=i;String section=names.get(i);chain=chain.thenCompose(x->click(slot)).thenCompose(x->guiReady(section));}return chain;}).thenCompose(v->main(()->{var click=new org.bukkit.event.inventory.InventoryClickEvent(operator.getOpenInventory(),org.bukkit.event.inventory.InventoryType.SlotType.CONTAINER,18,org.bukkit.event.inventory.ClickType.SHIFT_LEFT,org.bukkit.event.inventory.InventoryAction.MOVE_TO_OTHER_INVENTORY);plugin.getServer().getPluginManager().callEvent(click);check(click.isCancelled(),"Administrative GUI allowed item transfer");operator.closeInventory();return true;}));}
    private CompletionStage<Boolean> guiLocales(){return main(()->{operator.performCommand("rep language ru_RU");return true;}).thenCompose(v->poll(()->main(()->profiles.cachedLanguage(operator.getUniqueId())==org.dextur.reputation.domain.PlayerLanguage.ru_RU),Boolean::booleanValue,0)).thenCompose(v->main(()->{operator.performCommand("repadmin gui Phase7Target");check(plain(operator.getOpenInventory().title()).equals("Администрирование репутации"),"RU admin GUI title");return true;})).thenCompose(v->guiReady("INSPECT")).thenCompose(v->main(()->{operator.closeInventory();operator.performCommand("rep language en_US");return true;})).thenCompose(v->poll(()->main(()->profiles.cachedLanguage(operator.getUniqueId())==org.dextur.reputation.domain.PlayerLanguage.en_US),Boolean::booleanValue,0)).thenCompose(v->main(()->{operator.performCommand("repadmin gui Phase7Target");check(plain(operator.getOpenInventory().title()).equals("Reputation administration"),"EN admin GUI title");return true;})).thenCompose(v->guiReady("INSPECT")).thenCompose(v->main(()->{operator.closeInventory();plugin.getLogger().info("PROBE_ADMIN7_GUI_LOCALES_PASS: real RU/EN inventories");return true;}));}
    private CompletionStage<Boolean> offlineInspection(){return main(()->{voter.kick(Component.text("Phase 7 known offline inspection"));return true;}).thenCompose(v->poll(()->main(()->plugin.getServer().getPlayer(voter.getUniqueId())==null),Boolean::booleanValue,0)).thenCompose(v->capture(false,"inspect","Phase7Voter")).thenCompose(replies->poll(()->main(()->replies.stream().anyMatch(text->text.contains(voter.getUniqueId().toString()))),Boolean::booleanValue,0)).thenCompose(v->read(Section.TRUST,voter.getUniqueId(),null)).thenCompose(before->console("repadmin recalculate trust Phase7Voter Offline verified facts").thenCompose(x->poll(()->read(Section.TRUST,voter.getUniqueId(),null),after->Long.parseLong(after.summary().get("trust_revision"))>Long.parseLong(before.summary().get("trust_revision")),0))).thenApply(v->{plugin.getLogger().info("PROBE_ADMIN7_OFFLINE_PASS: known offline inspect/recalculation without name-network lookup");return true;});}
    private CompletionStage<Boolean> guiModeration(){return main(()->{operator.performCommand("repadmin gui Phase7Target");return true;}).thenCompose(v->guiReady("INSPECT")).thenCompose(v->click(1)).thenCompose(v->guiReady("VOTES")).thenCompose(v->click(18)).thenCompose(v->guiReady("VOTE")).thenCompose(v->click(18)).thenCompose(v->waitTicks(6)).thenCompose(v->click(40)).thenCompose(v->outcome(pending,VoteProcessingOutcome.Status.INVALIDATED)).thenCompose(v->console("repadmin restore "+pending+" GUI test restoration")).thenCompose(v->outcome(pending,VoteProcessingOutcome.Status.ACCEPTED))
        .thenCompose(v->main(()->{operator.performCommand("repadmin gui Phase7Target");return true;})).thenCompose(v->guiReady("INSPECT")).thenCompose(v->click(1)).thenCompose(v->guiReady("VOTES")).thenCompose(v->click(18)).thenCompose(v->guiReady("VOTE")).thenCompose(v->click(18))
        .thenCompose(v->console("repadmin invalidate "+pending+" Concurrent stale GUI test")).thenCompose(v->outcome(pending,VoteProcessingOutcome.Status.INVALIDATED)).thenCompose(v->auditIds()).thenCompose(before->waitTicks(6).thenCompose(x->click(40)).thenCompose(x->waitTicks(6)).thenCompose(x->auditIds()).thenApply(after->{check(before.equals(after),"Stale GUI confirmation executed a second mutation");return true;}))
        .thenCompose(v->console("repadmin restore "+pending+" Restore after stale GUI")).thenCompose(v->outcome(pending,VoteProcessingOutcome.Status.ACCEPTED)).thenApply(v->{plugin.getLogger().info("PROBE_ADMIN_GUI_PASS: native navigation, explicit confirmation, stale snapshot rejection and item protection");return true;});}
    private CompletionStage<Boolean> localesAndReadCommands(){return capture(false,"inspect","Phase7Target").thenCombine(capture(true,"inspect","Phase7Target"),(ru,en)->List.of(ru,en)).thenCompose(replies->poll(()->main(()->replies.get(0).stream().anyMatch(t->t.contains("Видимая репутация"))&&replies.get(1).stream().anyMatch(t->t.contains("Visible reputation"))),Boolean::booleanValue,0)).thenCompose(v->{CompletionStage<Boolean> chain=CompletableFuture.completedFuture(true);for(String[] args:List.of(new String[]{"history","Phase7Target","votes"},new String[]{"history","Phase7Target","admin"},new String[]{"history","Phase7Target","trust"},new String[]{"history","Phase7Target","recovery"},new String[]{"history","Phase7Target","flags"},new String[]{"trust","Phase7Target"},new String[]{"flags","Phase7Target"},new String[]{"relations","Phase7Target"},new String[]{"audit","Phase7Target"},new String[]{"pending","Phase7Target"}))chain=chain.thenCompose(x->capture(false,args)).thenCompose(reply->poll(()->main(()->!reply.isEmpty()),Boolean::booleanValue,0));return chain;}).thenApply(v->{plugin.getLogger().info("PROBE_ADMIN7_LOCALES_PASS: registered inspect/history/trust/flags/relations/audit/pending commands in RU/EN");return true;});}
    private CompletionStage<List<String>> capture(boolean english,String...args){var replies=new CopyOnWriteArrayList<String>();return main(()->{CommandSender sender=(CommandSender)java.lang.reflect.Proxy.newProxyInstance(plugin.getClass().getClassLoader(),new Class<?>[]{english?Player.class:CommandSender.class},(proxy,method,values)->{if(method.getName().equals("sendMessage")&&values!=null)for(Object value:values)if(value instanceof Component c)replies.add(plain(c));return switch(method.getName()){case "hasPermission","isPermissionSet","isOp","isOnline"->true;case "getUniqueId"->operator.getUniqueId();case "getName","toString"->"Phase7LocaleProbe";case "getServer"->plugin.getServer();case "hashCode"->System.identityHashCode(proxy);case "equals"->proxy==values[0];default->method.getReturnType()==boolean.class?false:null;};});plugin.getServer().getPluginCommand("repadmin").execute(sender,"repadmin",args);return replies;});}
    private CompletionStage<String> auditIds(){return auditIds(1,new TreeSet<>());}
    private CompletionStage<String> auditIds(int page,Set<String> ids){return admin.read(new Query(Section.AUDIT,"global",target.getUniqueId(),null,Filter.empty(),page,28)).thenCompose(report->{for(var row:report.rows())ids.add(row.id().toString());if(report.rows().size()==28&&page<100)return auditIds(page+1,ids);return CompletableFuture.completedFuture(String.join("\n",ids));});}
    private CompletionStage<Report> read(Section section,UUID player,UUID id){return admin.read(new Query(section,"global",player,id,Filter.empty(),1,28));}
    private CompletionStage<Boolean> outcome(UUID vote,VoteProcessingOutcome.Status status){return poll(()->voting.outcome(vote),r->r.status()==status,0).thenApply(v->true);}
    private CompletionStage<Boolean> console(String command){return main(()->{plugin.getServer().dispatchCommand(plugin.getServer().getConsoleSender(),command);return true;});}
    private CompletionStage<Boolean> click(int slot){return main(()->{var event=new org.bukkit.event.inventory.InventoryClickEvent(operator.getOpenInventory(),org.bukkit.event.inventory.InventoryType.SlotType.CONTAINER,slot,org.bukkit.event.inventory.ClickType.LEFT,org.bukkit.event.inventory.InventoryAction.PICKUP_ALL);plugin.getServer().getPluginManager().callEvent(event);check(event.isCancelled(),"Admin click not cancelled");return true;});}
    private CompletionStage<Boolean> guiReady(String section){return poll(()->main(()->{var holder=operator.getOpenInventory().getTopInventory().getHolder();if(holder==null||!holder.getClass().getName().endsWith("InvestigationGui$Session"))return false;var f=holder.getClass().getDeclaredField("section");f.setAccessible(true);var b=holder.getClass().getDeclaredField("busy");b.setAccessible(true);return f.get(holder).toString().equals(section)&&!b.getBoolean(holder)&&operator.getOpenInventory().getTopInventory().getItem(0)!=null;}),Boolean::booleanValue,0);}
    private boolean papi()throws Exception{if(!plugin.getServer().getPluginManager().isPluginEnabled("PlaceholderAPI"))return true;var papi=plugin.getServer().getPluginManager().getPlugin("PlaceholderAPI");var type=Class.forName("me.clip.placeholderapi.PlaceholderAPI",true,papi.getClass().getClassLoader());var method=type.getMethod("setPlaceholders",org.bukkit.OfflinePlayer.class,String.class);String value=String.valueOf(method.invoke(null,target,"%dexturreputation_health_modifier%"));if(value.isEmpty())return false;check(value.equals("1"),"Health/PAPI regression after moderation: "+value);check(method.invoke(null,target,"%dexturreputation_score%").equals("100"),"Score PAPI regression");check(method.invoke(null,target,"%dexturreputation_policy_chat_send%").equals("ALLOW"),"Policy PAPI regression");plugin.getLogger().info("PROBE_ADMIN7_PAPI_PASS: full parser after moderation/recalculation");return true;}
    private CompletionStage<Boolean> waitTicks(long ticks){var result=new CompletableFuture<Boolean>();plugin.getServer().getScheduler().runTaskLater(plugin,()->result.complete(true),ticks);return result;}
    private <T> CompletionStage<T> poll(Supplier<? extends CompletionStage<T>> read,Predicate<T> ready,int attempt){return read.get().thenCompose(value->{if(ready.test(value))return CompletableFuture.completedFuture(value);if(attempt>300)return CompletableFuture.failedFuture(new AssertionError("Administration wait timed out: "+value));return waitTicks(2).thenCompose(v->poll(read,ready,attempt+1));});}
    private <T> CompletableFuture<T> main(Callable<T> action){var result=new CompletableFuture<T>();Runnable task=()->{try{result.complete(action.call());}catch(Throwable e){result.completeExceptionally(e);}};if(Bukkit.isPrimaryThread())task.run();else plugin.getServer().getScheduler().runTask(plugin,task);return result;}
    private static String plain(Component c){return PlainTextComponentSerializer.plainText().serialize(c);}
    private static void check(boolean condition,String message){if(!condition)throw new AssertionError(message);}
}
